'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='circuitbench.project.v1',PREF='circuitbench.preferences.v1';
let p=CB.sample(),prefs={theme:'light',mode:'easy',left:'library',leftHidden:innerWidth<851,rightHidden:innerWidth<851},loadError='',previous='';
try{let raw=localStorage.getItem(KEY);if(raw){p=CB.validate(JSON.parse(raw));previous=raw;}let pr=localStorage.getItem(PREF);if(pr)Object.assign(prefs,JSON.parse(pr));}catch(e){loadError='The local save could not be read. Use Project → Download recovery data to preserve it. '+e.message;}
let view='pcb',tool='select',selected=null,activeNet='',history=[],future=[],saveTimer,route=null,wire=null,drag=null,pan=null,lastPoint={x:30,y:20},libraryQuery='',checkFilter='all',bomSort='ref',showRats=true,showOther=true,showLabels=true,showWireMap=false,zoom={pcb:{cx:30,cy:20,w:88},sch:{cx:60,cy:42,w:150}},undoLimit=60;
const svg=$('#canvas');
function say(text){$('#status').textContent=text;}
function savePrefs(){try{localStorage.setItem(PREF,JSON.stringify(prefs));}catch(e){say('Preferences could not be saved.');}}
function checkpoint(){history.push(JSON.stringify(p));if(history.length>undoLimit)history.shift();future=[];}
function persist(){clearTimeout(saveTimer);$('#saveState').textContent='◌ Saving…';saveTimer=setTimeout(()=>{saveTimer=null;try{let current=JSON.stringify(p);if(previous&&previous!==current)localStorage.setItem(KEY+'.backup',previous);localStorage.setItem(KEY,current);previous=current;$('#saveState').textContent='● Saved locally';}catch(e){$('#saveState').textContent='! Save failed';say('Local storage is unavailable or full. Save JSON now to protect your work.');}},200);}
function changed(message='Design updated.'){persist();render();say(message);}
function edit(fn,message){let before=JSON.stringify(p);checkpoint();try{fn();p=CB.validate(p);changed(message);}catch(e){p=JSON.parse(before);history.pop();render();say(e.message);}}
function undo(redo=false){let from=redo?future:history,to=redo?history:future;if(!from.length)return;to.push(JSON.stringify(p));p=JSON.parse(from.pop());selected=null;route=null;wire=null;changed(redo?'Redone.':'Undone.');}
function options(items,value){return items.map(x=>{let [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('');}
function field(label,name,value,type='text',extra=''){return `<label>${label}<input ${extra} type="${type}" data-field="${name}" value="${esc(value)}"></label>`;}
function selectedObject(){if(!selected)return null;return p.components.find(c=>c.id===selected)||p.tracks.find(t=>t.id===selected)||p.vias.find(v=>v.id===selected);}
function isComponent(x){return x&&Array.isArray(x.pads);}
function applyTheme(){document.body.dataset.theme=prefs.theme;$('#theme').value=prefs.theme;$('#mode').value=prefs.mode;$('#shell').classList.toggle('hideLeft',!!prefs.leftHidden);$('#shell').classList.toggle('hideRight',!!prefs.rightHidden);}
function render(){applyTheme();$('#projectTitle').textContent=p.title;$('#canvasProject').textContent=p.title;$('#canvasEyebrow').textContent=view==='sch'?'NET-LABELED SCHEMATIC':'TWO-LAYER BOARD';$('#canvasSubtitle').textContent=view==='sch'?`${p.components.length} components · ${p.nets.length} nets`:`${p.board.width} × ${p.board.height} mm · Revision ${p.revision}`;$('#undoButton').disabled=!history.length;$('#redoButton').disabled=!future.length;$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',b.dataset.view===view);});$$('[data-tool]').forEach(b=>{b.classList.toggle('active',b.dataset.tool===tool);b.setAttribute('aria-pressed',b.dataset.tool===tool);});$('#stage').hidden=view==='review';$('#review').hidden=view!=='review';$('#editorToolbar').hidden=view==='review';$('#connectTool').hidden=view!=='sch';for(let id of ['routeTool','viaTool','layerLabel','widthLabel'])$('#'+id).hidden=view!=='pcb';renderLeft();renderInspector();if(view==='review')renderReview();else renderCanvas();let errors=CB.checks(p).filter(f=>f.severity==='error').length;$('#checkBadge').textContent=errors?errors:'';}
function renderLeft(){let q=libraryQuery.toLowerCase();$$('[data-left]').forEach(b=>b.classList.toggle('active',b.dataset.left===prefs.left));$('#search').placeholder=prefs.left==='library'?'Search parts…':'Find a component…';if(prefs.left==='library'){$('#leftContent').innerHTML=CB.defs.filter(d=>(d.name+' '+d.value).toLowerCase().includes(q)).map(d=>`<button class="part" data-add="${d.key}"><span class="glyph">${({resistor:'─▭─',capacitor:'─Ⅱ─',electrolytic:'⊕',led:'⇗◉',diode:'─▷│',smd2:'▪ ▪'})[d.key]||'▥'}</span><span><strong>${esc(d.name.split(' · ')[0])}</strong><small>${esc(d.name.split(' · ')[1])}</small></span><span class="plus">+</span></button>`).join('')||'<p class="empty">No matching parts. Try a generic IC or custom terminal block.</p>';}else{$('#leftContent').innerHTML=p.components.filter(c=>(c.ref+' '+c.value).toLowerCase().includes(q)).map(c=>`<button class="part ${selected===c.id?'selected':''}" data-select="${c.id}"><span class="glyph">${esc(c.ref.replace(/\d+/g,''))}</span><span><strong>${esc(c.ref)} · ${esc(c.value)}</strong><small>${esc(c.kind)} / ${c.pads.length} pins</small></span></button>`).join('')||'<p class="empty">Your board is empty. Choose Add parts to begin.</p>';$('#leftContent').innerHTML+=`<div class="inspectSection"><h4>Nets</h4>${p.nets.map(n=>`<button class="netchip" data-net="${esc(n)}">${esc(n)}</button>`).join('')}<button class="textbutton" data-action="nets">Manage nets →</button></div>`;}}
function renderInspector(){let x=selectedObject(),advanced=prefs.mode==='advanced';$('#selectionType').textContent=x?(isComponent(x)?'COMPONENT':x.points?'TRACK':'VIA'):'PROJECT';let s='';if(isComponent(x)){let pos=x[view==='sch'?'sch':'pcb'];s=`<div class="inspectSection"><h3>${esc(x.ref)} <small>${esc(x.kind)}</small></h3>${field('Reference','ref',x.ref)}${field('Value / description','value',x.value)}${advanced?field('Manufacturer part number','mpn',x.mpn):''}<div class="row2">${field('X '+(view==='sch'?'drawing units':'mm'),'x',pos.x,'number','step="0.1"')}${field('Y '+(view==='sch'?'drawing units':'mm'),'y',pos.y,'number','step="0.1"')}</div><div class="row2">${field('Rotation °','rotation',pos.rotation,'number','step="90" min="0" max="359"')}${view!=='sch'?`<label>Board side<select data-field="side">${options([['F','Front'],['B','Back']],x.pcb.side)}</select></label>`:''}</div><div class="buttonrow"><button data-action="rotate">↻ Rotate</button><button data-action="duplicate">Duplicate</button><button data-action="delete" class="danger">Delete</button></div><div class="buttonrow"><button data-action="crossprobe">Show in ${view==='sch'?'PCB':'schematic'} →</button></div></div><div class="inspectSection"><h4>Pins & nets</h4>${CB.logicalPads(x).map(a=>`<div class="pinrow"><span><strong>${esc(a.n)} · ${esc(a.name)}</strong><small>${esc(a.type)}</small></span><select aria-label="${esc(x.ref)} pin ${esc(a.n)} net" data-pin-net="${esc(a.pin||a.n)}">${options([['','Unassigned'],...p.nets.map(n=>[n,n]),['__NC__','Intentional NC']],a.nc?'__NC__':a.net)}</select></div>`).join('')}<button class="textbutton" data-action="nets">+ Manage nets</button>${advanced?'<div class="buttonrow"><button data-action="footprint">Edit footprint & pin types</button></div>':'<p>Advanced mode exposes footprint geometry and pin types.</p>'}</div>`;}else if(x&&x.points){s=`<div class="inspectSection"><h3>Copper track</h3><label>Net<select data-field="net">${options(p.nets,x.net)}</select></label><label>Layer<select data-field="layer">${options([['F','Front'],['B','Back']],x.layer)}</select></label>${field('Width mm','width',x.width,'number','min="0.05" max="10" step="0.05"')}<p>${x.points.length-1} segments · ${x.points.slice(1).reduce((s,b,i)=>s+CB.dist(x.points[i],b),0).toFixed(2)} mm</p><div class="buttonrow"><button data-action="vertices">Edit points</button><button data-action="delete" class="danger">Delete track</button></div></div>`;}else if(x){s=`<div class="inspectSection"><h3>Plated via</h3><label>Net<select data-field="net">${options(p.nets,x.net)}</select></label><div class="row2">${field('X mm','viaX',x.x,'number','step="0.1"')}${field('Y mm','viaY',x.y,'number','step="0.1"')}</div><div class="row2">${field('Diameter mm','diameter',x.diameter,'number','step="0.05"')}${field('Drill mm','drill',x.drill,'number','step="0.05"')}</div><button data-action="delete" class="danger">Delete via</button></div>`;}else{let total=CB.connections(p,'sch').length,remaining=CB.connections(p).length;s=`<div class="inspectSection"><h3>From idea to copper.</h3><p>Build a schematic. Place your parts. Route the connections.</p><div class="metric"><strong>${p.components.length}</strong><span>components</span><strong style="margin-left:18px">${p.nets.length}</strong><span>nets</span></div><h4>Routing progress</h4><div class="meter"><span style="width:${total?Math.max(0,100-remaining/total*100):0}%"></span></div><p>${remaining} connection${remaining===1?'':'s'} to route</p><div class="buttonrow"><button data-action="routeDialog">Connect by pin number</button></div></div><div class="inspectSection"><h4>Board setup</h4><div class="row2">${field('Width mm','boardWidth',p.board.width,'number','min="5" max="500"')}${field('Height mm','boardHeight',p.board.height,'number','min="5" max="500"')}</div>${advanced?field('Thickness mm','thickness',p.board.thickness,'number','min="0.1" max="10" step="0.1"'):''}<p>2 copper layers · rectangular outline</p><button class="textbutton" data-action="project">Project & recovery →</button></div>`;}
 if(view!=='review')s+=`<div class="inspectSection"><h4>${view==='sch'?'Drawing':'Layer visibility'}</h4>${view==='sch'?`<label class="inlinecheck"><input type="checkbox" id="showWireMap" ${showWireMap?'checked':''}> Connection map overlay</label><p>Pins with matching net labels are connected. The optional map is a topology guide; crossing lines never join.</p>`:''}${view!=='sch'?`<label class="inlinecheck"><input type="checkbox" id="showRats" ${showRats?'checked':''}> Airwires (unrouted)</label><label class="inlinecheck"><input type="checkbox" id="showOther" ${showOther?'checked':''}> Show inactive copper (dimmed)</label><div class="legend"><span><i class="dot" style="background:#eea574"></i>Front copper</span><small>F.Cu</small></div><div class="legend"><span><i class="dot" style="background:#67b5f3"></i>Back copper</span><small>B.Cu</small></div>`:''}<label class="inlinecheck"><input type="checkbox" id="showLabels" ${showLabels?'checked':''}> Reference labels</label><p class="helptext">Select with a click or Design tree. Move with drag, arrow keys, or X/Y fields.</p></div>`;
 if(advanced)s+=`<div class="inspectSection"><h4>Design rules · mm</h4>${[['clearance','Copper clearance'],['edge','Copper to edge'],['minWidth','Minimum track width'],['annular','Minimum annular ring'],['mask','Mask expansion']].map(([k,l])=>field(l,'rule:'+k,p.rules[k],'number','step="0.05" min="0" max="5"')).join('')}</div>`;
 $('#inspector').innerHTML=s;}
function pcbBackView(){return view==='pcb'&&prefs.boardView==='B';}
function viewBox(){let z=zoom[view==='sch'?'sch':'pcb'],r=svg.getBoundingClientRect(),h=z.w*(r.height||500)/(r.width||700);return {x:(pcbBackView()?p.board.width-z.cx:z.cx)-z.w/2,y:z.cy-h/2,w:z.w,h};}
function fit(){if(view==='review')return;let z=zoom[view],r=svg.getBoundingClientRect(),aspect=(r.width||700)/(r.height||500);if(view==='pcb'){z.cx=p.board.width/2;z.cy=p.board.height/2+1;z.w=Math.max(p.board.width*1.4,p.board.height*aspect*1.8);}else{let ps=CB.pads(p,'sch'),xs=ps.map(a=>a.x),ys=ps.map(a=>a.y),minX=xs.length?Math.min(...xs):0,maxX=xs.length?Math.max(...xs):100,minY=ys.length?Math.min(...ys):0,maxY=ys.length?Math.max(...ys):70;z.cx=(minX+maxX)/2;z.cy=(minY+maxY)/2;z.w=Math.max((maxX-minX+25)*1.25,(maxY-minY+30)*aspect*1.4,60);}renderCanvas();}
function line(a,b,color,width,extra=''){return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="${color}" stroke-width="${width}" ${extra}/>`;}
function path(points){return points.map((q,i)=>(i?'L':'M')+q.x+','+q.y).join(' ');}
function terminalAttrs(id,n){return `data-terminal="${id}" data-pin="${esc(n)}"`;}
function boardSVG(forPrint=false){let out=`<rect x="0" y="0" width="${p.board.width}" height="${p.board.height}" rx="0.5" fill="#153e35" stroke="#67967b" stroke-width="0.22"/><rect x=".65" y=".65" width="${p.board.width-1.3}" height="${p.board.height-1.3}" rx="0.3" fill="url(#boardgrid)" opacity=".4" pointer-events="none"/>`;
 for(let layer of ['B','F']){if(!showOther&&layer!==$('#layer').value&&!forPrint)continue;for(let t of p.tracks.filter(t=>t.layer===layer)){out+=`<path d="${path(t.points)}" fill="none" stroke="${layer==='F'?'#eea574':'#67b5f3'}" stroke-width="${t.width}" stroke-linecap="round" stroke-linejoin="round" data-object="${t.id}"/>`;if(t.id===selected&&!forPrint)out+=`<path d="${path(t.points)}" fill="none" stroke="#fff" stroke-width="${t.width+.35}" opacity=".6" stroke-dasharray=".8 .6" pointer-events="none"/>`;out+=`<path d="${path(t.points)}" fill="none" stroke="transparent" stroke-width="${Math.max(t.width,1.2)}" data-object="${t.id}"/>`;}}
 for(let c of p.components){let b=c.body,pos=c.pcb;out+=`<g data-object="${c.id}">`;let stroke=c.id===selected&&!forPrint?'#fff':'#9fbfab';out+=`<g transform="translate(${pos.x} ${pos.y}) rotate(${pos.rotation}) scale(${pos.side==='B'?-1:1} 1)" opacity="${!showOther&&pos.side!==$('#layer').value&&!forPrint?.25:1}"><rect x="${-b[0]/2}" y="${-b[1]/2}" width="${b[0]}" height="${b[1]}" rx=".25" fill="#1e483f" stroke="${stroke}" stroke-width="${c.id===selected?.3:.16}"/>`;
 if(c.kind==='led'||c.kind==='electrolytic')out+=`<circle r="2.5" fill="#2b6151" stroke="${stroke}" stroke-width=".15"/><path d="M-1 -1.5v3m-.7-1.5h1.4" stroke="${stroke}" stroke-width=".2"/>`;
 if(c.kind.startsWith('dip'))out+=`<path d="M-1.2 ${-b[1]/2} a1.2 1.2 0 0 0 2.4 0" fill="none" stroke="${stroke}" stroke-width=".2"/>`;
 out+='</g>';for(let a of c.pads){if(a.mount==='smd'&&!showOther&&c.pcb.side!==$('#layer').value&&!forPrint)continue;let q=CB.position(c,a),front=a.mount==='tht'||c.pcb.side==='F';out+=`<circle cx="${q.x}" cy="${q.y}" r="${a.diameter/2}" fill="${front?'#eeaf74':'#72bfff'}" stroke="${activeNet&&a.net===activeNet?'#fff':'#d4bc76'}" stroke-width="${activeNet&&a.net===activeNet?.25:.07}" ${terminalAttrs(c.id,a.n)}><title>${esc(c.ref+'.'+a.n+' '+a.name+' · '+(a.net||'unassigned'))}</title></circle>`;if(a.drill)out+=`<circle cx="${q.x}" cy="${q.y}" r="${a.drill/2}" fill="#0a1d18" pointer-events="none"/>`;if(a.n===c.pads[0].n)out+=`<circle cx="${q.x}" cy="${q.y}" r="${a.diameter/2+.26}" fill="none" stroke="#e3eacc" stroke-width=".12" pointer-events="none"/>`;}
 if(showLabels||forPrint)out+=`<text x="${pos.x}" y="${pos.y-Math.max(b[1]/2,2)-1.6}" font-size="1.3" fill="#f0f2d7" text-anchor="middle" font-family="monospace" pointer-events="none">${esc(c.ref)}</text><text x="${pos.x}" y="${pos.y+Math.max(b[1]/2,2)+2.3}" font-size=".95" fill="#adc9b8" text-anchor="middle" pointer-events="none">${esc(c.value)}</text>`;out+='</g>';}
 for(let v of p.vias)out+=`<g data-object="${v.id}"><circle cx="${v.x}" cy="${v.y}" r="${v.diameter/2}" fill="#dfbf73" stroke="${v.id===selected?'white':'#aecbbb'}" stroke-width=".15" ${terminalAttrs(v.id,'via')}/><circle cx="${v.x}" cy="${v.y}" r="${v.drill/2}" fill="#0a1d18" pointer-events="none"/></g>`;
 if(showRats&&!forPrint)for(let l of CB.connections(p))out+=line(l.a,l.b,activeNet===l.net?'#fff':'#b9d78a',.12,`stroke-dasharray=".7 .5" opacity=".7" pointer-events="none"`);
 out+=`<text x="3" y="${p.board.height-2.8}" fill="#8aaf9b" font-size="1.1" font-family="monospace" pointer-events="none">CIRCUITBENCH / REV ${esc(p.revision)}</text>`;return out;}
function schematicSVG(){let color=prefs.theme==='light'?'#387756':'#96d4a6',ink=prefs.theme==='light'?'#263d35':'#e1e9de',out='';if(showWireMap)for(let l of CB.connections(p,'sch')){let mid=(l.a.x+l.b.x)/2,points=[l.a,{x:mid,y:l.a.y},{x:mid,y:l.b.y},l.b];out+=`<path d="${path(points)}" fill="none" stroke="${l.net===activeNet?'#b47b24':color}" stroke-width=".35" pointer-events="none"/><text x="${mid+1}" y="${(l.a.y+l.b.y)/2-1.5}" font-family="monospace" font-size="1.9" fill="${color}" pointer-events="none">${esc(l.net)}</text>`;}
 for(let c of p.components){let t=c.sch,n=c.pads.length,half=Math.ceil(n/2),h=n===2?5:Math.max(7,half*5);out+=`<g data-object="${c.id}"><g transform="translate(${t.x} ${t.y}) rotate(${t.rotation})"><rect x="-7" y="${-h/2}" width="14" height="${h}" rx=".5" fill="${prefs.theme==='light'?'#f8faf0':'#1e362b'}" stroke="${selected===c.id?'#b67c26':ink}" stroke-width="${selected===c.id?.7:.4}"/>`;if(c.kind==='resistor'||c.kind==='smd2')out+=`<path d="M-5 0h1l1-2 2 4 2-4 2 4 1-2h1" fill="none" stroke="${ink}" stroke-width=".4"/>`;else if(c.kind.includes('capacitor')||c.kind==='electrolytic')out+=`<path d="M-5 0h4m0-2v4m2-4v4m0-2h4" stroke="${ink}" stroke-width=".5"/>`;else if(c.kind==='led'||c.kind==='diode')out+=`<path d="M-3-2L1 0 -3 2Z M1-2v4m-6-2h2m4 0h3" fill="none" stroke="${ink}" stroke-width=".4"/>`;
 out+='</g>';for(let a of c.pads){let q=CB.position(c,a,'sch'),local=CB.schLocal(c,a),inner=CB.rotate(Math.sign(local.x)*7,local.y,t.rotation),ip={x:t.x+inner.x,y:t.y+inner.y};out+=line(q,ip,ink,.35,`pointer-events="none"`);out+=`<circle cx="${q.x}" cy="${q.y}" r="1.15" fill="${a.net?color:'var(--panel)'}" stroke="${ink}" stroke-width=".25" ${terminalAttrs(c.id,a.n)}><title>${esc(c.ref+'.'+a.n+' '+a.name)}</title></circle><text x="${q.x+(local.x<0?-2:2)}" y="${q.y-1.8}" text-anchor="middle" font-size="1.8" fill="${ink}" pointer-events="none">${esc(a.n)}</text>`;if(!showWireMap&&a.net){let dir=CB.rotate(Math.sign(local.x),0,t.rotation),end={x:q.x+dir.x*7,y:q.y+dir.y*7};out+=line(q,end,color,.35,'pointer-events="none"');out+=`<text x="${end.x+(dir.x<0?-.8:.8)}" y="${end.y-1.2}" text-anchor="${dir.x<0?'end':'start'}" font-size="1.8" font-family="monospace" fill="${color}" pointer-events="none">${esc(a.net)}</text>`;}if(a.nc)out+=`<path d="M${q.x-1.3} ${q.y-1.3}l2.6 2.6m-2.6 0l2.6-2.6" stroke="#b76749" stroke-width=".4" pointer-events="none"/>`;}
 if(showLabels)out+=`<text x="${t.x}" y="${t.y-h/2-4}" text-anchor="middle" fill="${ink}" font-size="2.6" font-weight="bold" pointer-events="none">${esc(c.ref)}</text><text x="${t.x}" y="${t.y+h/2+5}" text-anchor="middle" fill="${ink}" font-size="2.2" pointer-events="none">${esc(c.value)}</text>`;out+='</g>';}
 return out;}
function renderCanvas(){if(view==='review')return;let v=viewBox();svg.setAttribute('viewBox',`${v.x} ${v.y} ${v.w} ${v.h}`);let grid=view==='sch'?1:Number($('#grid').value);svg.innerHTML=`<defs><pattern id="dots" width="${grid}" height="${grid}" patternUnits="userSpaceOnUse"><circle cx="0" cy="0" r="${Math.min(.065,grid*.09)}" fill="${prefs.theme==='light'?'#abb5a8':'#4d6457'}"/></pattern><pattern id="boardgrid" width="${grid}" height="${grid}" patternUnits="userSpaceOnUse"><circle cx="0" cy="0" r="${Math.min(.065,grid*.09)}" fill="#a1bca6"/></pattern></defs><rect x="${v.x}" y="${v.y}" width="${v.w}" height="${v.h}" fill="url(#dots)" pointer-events="none"/>`+`<g id="boardScene"${pcbBackView()?` transform="translate(${p.board.width} 0) scale(-1 1)"`:''}>`+(view==='pcb'?boardSVG():schematicSVG())+`<g id="live"></g></g>`;$('#zoomText').textContent=Math.round((view==='pcb'?88:150)/zoom[view].w*100)+'%';let hints={select:'Select a part to inspect it. Scroll to zoom · F to fit.',pan:'Drag the canvas to pan. Scroll to zoom.',connect:wire?'Choose the destination pin. Esc cancels.':'Click one pin, then another to connect their nets.',route:route?'Click corners, then a same-net pad or via to finish. Enter ends a free track.':'Start at a connected pad or via. Click to place corners.',via:'Choose a net in Design tree or select a pin, then click to place a via.'};$('#interactionHint').textContent=hints[tool]||hints.select;$('#finishRoute').hidden=!route;svg.style.cursor=tool==='pan'?'grab':tool==='select'?'default':'crosshair';drawLive();}
function drawLive(){let g=$('#live');if(!g)return;let out='';if(route)out+=`<path d="${path([...route.points,lastPoint])}" fill="none" stroke="${route.layer==='F'?'#ffe5a9':'#a0d5ff'}" stroke-width="${route.width}" stroke-linecap="round" opacity=".9" pointer-events="none"/>`;if(wire){let a=findTerminal(wire.id,wire.pin,'sch');if(a)out+=line(a,lastPoint,'#bf893c',.4,'stroke-dasharray="1 1" pointer-events="none"');}g.innerHTML=out;}
function setView(next){view=next;route=null;wire=null;tool='select';render();requestAnimationFrame(fit);}
function setTool(next){if(view==='review')setView('pcb');tool=next;route=null;wire=null;render();}
function pick(id){selected=id;let o=selectedObject();activeNet=isComponent(o)?'':o?.net||'';render();if(innerWidth<851){prefs.rightHidden=false;applyTheme();}say(isComponent(o)?`${o.ref} selected. Move with arrow keys or X/Y fields.`:'Object selected.');}
function addPart(key){let z=zoom[view==='sch'?'sch':'pcb'];edit(()=>{let c=CB.component(p,key,view==='pcb'?CB.round(z.cx):p.board.width/2,view==='pcb'?CB.round(z.cy):p.board.height/2);if(view==='sch'){c.sch.x=CB.round(z.cx);c.sch.y=CB.round(z.cy);}c.sheet=window.CBWorkbench?.getSheet()||'main';if(view==='pcb')c.pcb.side=$('#layer').value;p.components.push(c);selected=c.id;tool='select';},'Part placed at the center of the view. Drag it into position.');}
function point(e,snap=true){let r=svg.getBoundingClientRect(),v=viewBox(),q={x:v.x+(e.clientX-r.left)/r.width*v.w,y:v.y+(e.clientY-r.top)/r.height*v.h};if(pcbBackView())q.x=p.board.width-q.x;if(snap){let grid=view==='sch'?1:Number($('#grid').value);q.x=CB.round(Math.round(q.x/grid)*grid);q.y=CB.round(Math.round(q.y/grid)*grid);}return q;}
function findTerminal(id,pin,v='pcb'){let c=p.components.find(c=>c.id===id);if(c){let a=c.pads.find(a=>v==='sch'?(a.pin||a.n)===pin:a.n===pin);if(a)return {...CB.position(c,a,v),net:a.net,pad:a,component:c};}let via=p.vias.find(a=>a.id===id);return via?{...via}:null;}
function connectPins(a,b){let aa=findTerminal(a.id,a.pin,'sch'),bb=findTerminal(b.id,b.pin,'sch');if(!aa||!bb||!aa.pad||!bb.pad)return;if(a.id===b.id&&a.pin===b.pin)return say('Choose a different pin.');if(aa.net&&bb.net&&aa.net!==bb.net&&!confirm(`Merge nets ${aa.net} and ${bb.net}? All connected pads and tracks will use ${aa.net}.`))return;edit(()=>{let n=CB.mergeNet(p,aa.net,bb.net);aa.pad.net=n;bb.pad.net=n;aa.pad.nc=false;bb.pad.nc=false;activeNet=n;},'Pins connected. The PCB airwires updated.');}
function finishRoute(end){if(!route||route.points.length<1)return;if(end&&end.net!==route.net){say('That terminal belongs to a different net. Use the schematic to change connectivity.');return;}let points=CB.clone(route.points);if(end&&CB.dist(points.at(-1),end)>1e-7)points.push({x:end.x,y:end.y});if(points.length<2)return say('Add another point or choose a destination pad.');let r=route;edit(()=>{p.tracks.push({id:CB.uid(),net:r.net,layer:r.layer,width:r.width,points});route=null;},'Track committed. Check Review for clearances and remaining airwires.');}
svg.addEventListener('pointerdown',e=>{if(e.button!==0&&e.button!==1)return;e.preventDefault();let raw=point(e,false),q=point(e),terminal=e.target.closest('[data-terminal]'),object=e.target.closest('[data-object]');lastPoint=q;
 if(tool==='pan'||e.button===1){pan={clientX:e.clientX,clientY:e.clientY,z:CB.clone(zoom[view]),rect:svg.getBoundingClientRect()};svg.setPointerCapture(e.pointerId);return;}
 if(tool==='connect'){if(!terminal)return say('Choose a numbered pin. Wire crossings do not make junctions.');let ref={id:terminal.dataset.terminal,pin:terminal.dataset.pin};if(!wire){wire=ref;say('Choose the second pin.');renderCanvas();}else{let a=wire;wire=null;connectPins(a,ref);renderCanvas();}return;}
 if(tool==='route'){let a=terminal?findTerminal(terminal.dataset.terminal,terminal.dataset.pin):null;if(!route){if(!a?.net)return say('Start on a pad or via with an assigned net. Connect it in the schematic first.');if(a.pad?.mount==='smd'&&a.component.pcb.side!==$('#layer').value)return say('Choose the copper layer matching this SMD pad.');route={net:a.net,layer:$('#layer').value,width:Number($('#trackWidth').value),points:[{x:a.x,y:a.y}]};if(!Number.isFinite(route.width)||route.width<.05||route.width>10){route=null;return say('Track width must be 0.05–10 mm.');}activeNet=a.net;renderCanvas();}else if(a){if(a.pad?.mount==='smd'&&a.component.pcb.side!==route.layer)return say('A back/front transition requires a plated via.');finishRoute(a);}else{if(CB.dist(route.points.at(-1),q)>.001)route.points.push(q);renderCanvas();}return;}
 if(tool==='via'){if(!activeNet)return say('Choose a net in Design tree first, or select a pad.');edit(()=>{p.vias.push({id:CB.uid(),x:q.x,y:q.y,net:activeNet,diameter:.9,drill:.4});},'Plated via placed. It connects front and back copper on '+activeNet+'.');return;}
 if(object||terminal){let id=terminal?.dataset.terminal||object.dataset.object;selected=id;if(terminal){let a=findTerminal(id,terminal.dataset.pin,view);activeNet=a?.net||'';}else activeNet='';let obj=selectedObject();if(isComponent(obj)){drag={id,start:raw,original:CB.clone(obj[view]),before:JSON.stringify(p),moved:false};}else if(obj&&!obj.points&&Number.isFinite(obj.x)&&Number.isFinite(obj.y)){drag={id,start:raw,original:{x:obj.x,y:obj.y},before:JSON.stringify(p),moved:false};}render();svg.setPointerCapture(e.pointerId);}else{selected=null;activeNet='';renderInspector();renderCanvas();}
});
svg.addEventListener('pointermove',e=>{let q=point(e);lastPoint=q;$('#coordinates').textContent=`${q.x.toFixed(2)}, ${q.y.toFixed(2)} ${view==='pcb'?'mm':'u'}`;if(pan){let z=zoom[view];z.cx=pan.z.cx-(pcbBackView()?-1:1)*(e.clientX-pan.clientX)/pan.rect.width*pan.z.w;z.cy=pan.z.cy-(e.clientY-pan.clientY)/pan.rect.width*pan.z.w;renderCanvas();return;}if(drag){let raw=point(e,false),dx=raw.x-drag.start.x,dy=raw.y-drag.start.y;if(Math.hypot(dx,dy)<zoom[view].w/400&&!drag.moved)return;drag.moved=true;let obj=selectedObject(),pos=isComponent(obj)?obj[view]:obj,grid=view==='sch'?1:Number($('#grid').value);pos.x=CB.round(Math.round((drag.original.x+dx)/grid)*grid);pos.y=CB.round(Math.round((drag.original.y+dy)/grid)*grid);renderCanvas();return;}if(route||wire)drawLive();});
function endDrag(){if(drag?.moved){history.push(drag.before);if(history.length>undoLimit)history.shift();future=[];try{CB.validate(p);changed(view==='pcb'?'Placement updated. Existing copper stays in place; reroute displaced connections.':'Symbol moved.');}catch(e){p=JSON.parse(drag.before);history.pop();render();say(e.message);}}drag=null;pan=null;}
svg.addEventListener('pointerup',endDrag);svg.addEventListener('pointercancel',endDrag);
svg.addEventListener('wheel',e=>{e.preventDefault();let q=point(e,false),z=zoom[view],factor=Math.exp(e.deltaY*.001),newW=Math.max(10,Math.min(1500,z.w*factor)),r=newW/z.w;z.cx=q.x+(z.cx-q.x)*r;z.cy=q.y+(z.cy-q.y)*r;z.w=newW;renderCanvas();},{passive:false});
svg.addEventListener('contextmenu',e=>{e.preventDefault();if(route||wire){route=null;wire=null;renderCanvas();say('Pending connection canceled.');}else if(e.target.closest('[data-object]')){pick(e.target.closest('[data-object]').dataset.object);say('Object actions are in the inspector: rotate, duplicate, delete.');}});
function dialog(title,body){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;if(!$('#dialog').open)$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();}
function projectDialog(){dialog('Project & recovery',`<div class="row2"><label>Project name<input id="titleEdit" maxlength="160" value="${esc(p.title)}"></label><label>Revision<input id="revisionEdit" maxlength="40" value="${esc(p.revision)}"></label></div><button class="primary" data-action="projectApply">Apply details</button><h3>Keep your work</h3><p class="helptext">Autosave stays in this browser on this device and web address. Export JSON for a durable backup or to move projects. Your source files are never overwritten automatically.</p><div class="buttonrow"><button data-action="save">Save project JSON</button><button data-action="import">Open project JSON</button><button data-action="recover">Restore previous autosave</button><button data-action="rawRecovery">Download recovery data</button></div><h3>A fresh sheet</h3><div class="buttonrow"><button data-action="new">New empty project</button><button data-action="sample">Load example</button></div><p class="helptext">Replacing a project requires confirmation and can be undone in this session. Opening files accepts CIRCUITBENCH schema 1; native KiCad and LibrePCB files are not yet supported.</p>`);}
function helpDialog(){dialog('A small circuit, start to finish',`<p class="helptext">CIRCUITBENCH v${CB.VERSION} · An independent, local-first electronics workbench. Original implementation inspired by the schematic-to-board workflow of LibrePCB and KiCad.</p><div class="steps"><b>01</b><div><strong>Place & connect</strong><p>Add parts in Schematic. Choose Connect, then click two numbered pins. You can also assign the same named net in the inspector or use Connect by pin number. Matching terminal labels are connected. Enable the optional connection map to visualize the net topology; crossings never create junctions.</p></div><b>02</b><div><strong>Place & route</strong><p>Switch to PCB layout and arrange the footprints. Choose Route, click a pad, add corners, then click a pad on the same net. Circular pads with a ring mark pin 1. THT pads and vias join both layers. Tracks stay in place when components move.</p></div><b>03</b><div><strong>Check & make</strong><p>Review shows basic electrical, connectivity, copper clearance and edge findings. Export Gerber/drill, BOM, netlist and a printable report. Verify the exported layers independently before fabrication.</p></div></div><h3>Useful keys</h3><p><kbd>S</kbd> Select · <kbd>H</kbd> Pan · <kbd>W</kbd> Connect/route · <kbd>R</kbd> Rotate · <kbd>F</kbd> Fit · <kbd>Esc</kbd> Cancel · <kbd>Enter</kbd> Finish a track · <kbd>Delete</kbd> Delete selection · <kbd>Ctrl/⌘ Z</kbd> Undo</p><p class="helptext">Arrow keys move the selected part one grid step; Shift moves ten. Scroll zooms around the pointer. On touch screens, use Pan and the zoom buttons. Select parts by Design tree for numeric editing.</p><div class="notice">First release scope: two layers, rectangular boards, circular copper pads, straight manual track segments, terminal-based schematic connections. No simulation, native KiCad/LibrePCB import, zones, shove routing, 3D models, solder paste or manufacturing silkscreen. IC templates have passive pins until you assign electrical types in Advanced mode.</div><p class="helptext">Every part stores its own footprint and pin mapping. Generic templates are starting dimensions, not a verified component library. Advanced → Edit footprint lets you set the actual geometry. No telemetry, remote libraries or account required. GNU GPL v3.</p>`);}
function netsDialog(){dialog('Named connections',`<p class="helptext">Pins on the same net are electrically connected in the schematic. Copper must still be routed on the board.</p><label>New net name<input id="newNet" maxlength="60" placeholder="e.g. +3V3, SDA, GND"></label><button data-action="addNet" class="primary">Add net</button><div class="tablewrap"><table><thead><tr><th>Name</th><th>Pins</th><th>Actions</th></tr></thead><tbody>${p.nets.map(n=>`<tr><td><input value="${esc(n)}" data-rename-net="${esc(n)}" maxlength="60" aria-label="Rename ${esc(n)}"></td><td>${CB.pads(p).filter(a=>a.net===n).length}</td><td><button data-remove-net="${esc(n)}">Delete</button></td></tr>`).join('')}</tbody></table></div><p class="helptext">Deleting a net also removes its tracks and vias and unassigns its pins. Undo restores the complete change.</p>`);}
function footprintDialog(){let c=selectedObject();if(!isComponent(c))return;dialog(c.ref+' · Footprint & pins',`<p class="helptext">Pin numbers are the shared identity between schematic terminals and physical pads. Coordinates below are local to the component center, in mm. Front-view geometry is mirrored when placed on the back.</p><div class="row2"><label>Body width mm<input id="bodyWidth" type="number" value="${c.body[0]}" min="0.1" max="100" step="0.1"></label><label>Body height mm<input id="bodyHeight" type="number" value="${c.body[1]}" min="0.1" max="100" step="0.1"></label></div><div class="tablewrap"><table id="padTable"><thead><tr><th>Pin</th><th>Name</th><th>X</th><th>Y</th><th>Ø pad</th><th>Ø drill</th><th>Mount</th><th>Type</th><th></th></tr></thead><tbody>${c.pads.map(padRow).join('')}</tbody></table></div><div class="buttonrow"><button data-action="addPad">+ Add pin</button><button class="primary" data-action="applyFootprint">Apply footprint</button></div><div id="footprintError" role="alert" class="helptext"></div><p class="helptext">Only circular pads are supported in v0.1. SMD pads require drill = 0. Through-hole pads require a positive drill smaller than the pad. Pin-1 ring, body outlines and reference labels are assembly guides only.</p>`);}
function padRow(a){return `<tr data-pad-row data-net-value="${esc(a.net)}" data-nc-value="${a.nc}">${['n','name','x','y','diameter','drill'].map(k=>`<td><input data-pad-field="${k}" value="${esc(a[k])}" aria-label="Pin ${esc(a.n)} ${k}" ${['x','y','diameter','drill'].includes(k)?'type="number" step="0.01"':'maxlength="60"'}></td>`).join('')}<td><select data-pad-field="mount" aria-label="Pin mount">${options(['tht','smd'],a.mount)}</select></td><td><select data-pad-field="type" aria-label="Pin type">${options(['passive','input','output','power_in','power_out','bidirectional'],a.type)}</select></td><td><button data-action="removePadRow" aria-label="Remove pin">×</button></td></tr>`;}
function applyFootprint(){let c=selectedObject(),original=CB.clone(c);let newpads=$$('#padTable tbody tr').map(row=>{let a={net:row.dataset.netValue,nc:row.dataset.ncValue==='true'};row.querySelectorAll('[data-pad-field]').forEach(e=>a[e.dataset.padField]=['x','y','diameter','drill'].includes(e.dataset.padField)?Number(e.value):e.value);return a;});try{c.body=[Number($('#bodyWidth').value),Number($('#bodyHeight').value)];c.pads=newpads;CB.validate(p);let updated=CB.clone(c);Object.assign(c,original);edit(()=>Object.assign(c,updated),'Footprint updated. Rerun checks after changing geometry.');closeDialog();}catch(e){Object.assign(c,original);$('#footprintError').textContent=e.message;}}
function routeDialog(){let terminals=CB.pads(p,view==='sch'?'sch':'pcb'),list=terminals.map(a=>[a.id,a.label+' · '+(a.net||'unassigned')]);dialog(view==='sch'?'Connect schematic pins':'Route between pins',`<p class="helptext">${view==='sch'?'Join two pins to the same net.':'Create an L-shaped copper route between two pins already assigned to the same net. Review the result for collisions.'}</p><label>From<select id="routeFrom">${options(list,list[0]?.[0])}</select></label><label>To<select id="routeTo">${options(list,list[1]?.[0])}</select></label>${view!=='sch'?`<div class="row2"><label>Layer<select id="routeLayer">${options([['F','Front'],['B','Back']],$('#layer').value)}</select></label><label>Width mm<input id="routeWidth" type="number" value="${$('#trackWidth').value}" min="0.05" max="10" step="0.05"></label></div><label>Bend<select id="routeBend"><option value="x">Horizontal first</option><option value="y">Vertical first</option></select></label>`:''}<button data-action="routeApply" class="primary">${view==='sch'?'Connect pins':'Create track'}</button><p id="routeError" role="alert"></p>`);}
function routeApply(){let from=$('#routeFrom').value,to=$('#routeTo').value;if(!from||!to||from===to){$('#routeError').textContent='Choose two different pins.';return;}let [aId,aPin]=from.split(':'),[bId,bPin]=to.split(':');if(view==='sch'){closeDialog();connectPins({id:aId,pin:aPin},{id:bId,pin:bPin});return;}let a=findTerminal(aId,aPin),b=findTerminal(bId,bPin),layer=$('#routeLayer').value,width=Number($('#routeWidth').value);if(!a.net||a.net!==b.net){$('#routeError').textContent='Both pins must be assigned to the same net in the schematic.';return;}if([a,b].some(t=>t.pad.mount==='smd'&&t.component.pcb.side!==layer)){$('#routeError').textContent='The selected layer does not match an SMD pad.';return;}if(!Number.isFinite(width)||width<.05||width>10){$('#routeError').textContent='Width must be 0.05–10 mm.';return;}let elbow=$('#routeBend').value==='x'?{x:b.x,y:a.y}:{x:a.x,y:b.y};edit(()=>p.tracks.push({id:CB.uid(),net:a.net,layer,width,points:[{x:a.x,y:a.y},elbow,{x:b.x,y:b.y}]}),'Track added. Check for collisions in Review.');closeDialog();}
function verticesDialog(){let t=selectedObject();if(!t?.points)return;dialog('Track points · millimeters',`<div class="tablewrap"><table id="vertexTable"><thead><tr><th>Point</th><th>X mm</th><th>Y mm</th></tr></thead><tbody>${t.points.map((q,i)=>`<tr><td>${i+1}</td><td><input type="number" step="0.01" value="${q.x}" aria-label="Point ${i+1} X"></td><td><input type="number" step="0.01" value="${q.y}" aria-label="Point ${i+1} Y"></td></tr>`).join('')}</tbody></table></div><button data-action="applyVertices" class="primary">Apply points</button>`);}
function deleteSelected(){let x=selectedObject();if(!x)return;edit(()=>{p.components=p.components.filter(c=>c.id!==selected);p.tracks=p.tracks.filter(c=>c.id!==selected);p.vias=p.vias.filter(c=>c.id!==selected);selected=null;},isComponent(x)?'Part removed. Existing tracks remain for inspection or deletion.':'Copper removed.');}
function rotateSelected(){let x=selectedObject();if(!isComponent(x))return;edit(()=>x[view==='sch'?'sch':'pcb'].rotation=(x[view==='sch'?'sch':'pcb'].rotation+90)%360,'Rotated 90°.');}
function duplicateSelected(){let c=selectedObject();if(!isComponent(c))return;edit(()=>{let n=CB.clone(c),prefix=c.ref.replace(/[0-9]+$/,'')||'X',i=1;while(p.components.some(c=>c.ref===prefix+i))i++;n.id=CB.uid();n.ref=prefix+i;n.pcb.x+=5;n.pcb.y+=5;n.sch.x+=10;n.sch.y+=10;n.pads.forEach(a=>{a.net='';a.labelNet='';a.nc=false;});p.components.push(n);selected=n.id;},'Duplicate created with unassigned pins.');}
function newProject(sample=false){if(p.components.length&&!confirm((sample?'Load the example':'Start an empty project')+'? Export JSON first if you need a separate copy. You can Undo this replacement.'))return;checkpoint();p=sample?CB.sample():CB.fresh();selected=null;activeNet='';route=null;wire=null;closeDialog();changed(sample?'Example loaded.':'Empty project ready. Add a component to begin.');fit();}
function download(name,content,mime='text/plain'){let blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);say(name+' exported.');}
function slug(){return p.title.replace(/[^a-z0-9_-]/gi,'-').replace(/-+/g,'-').slice(0,80)||'circuit';}
function exportDialog(){let fs=CB.checks(p),errors=fs.filter(f=>f.severity==='error').length;dialog('Take it to the bench',`<p class="helptext">${esc(p.title)} · Revision ${esc(p.revision)} · ${p.board.width} × ${p.board.height} mm</p><div class="notice">${errors?errors+' error findings remain. Exports include their current report.':'No errors found by the implemented checks.'} Review fabrication files in an independent viewer before ordering. These are basic checks, not full KiCad/LibrePCB DRC.</div><div class="exportGrid"><button data-action="fab" class="primary"><strong>Fabrication ZIP ↗</strong><small>2 copper + 2 mask layers, outline, plated drill, BOM, netlist, JSON & check report</small></button><button data-action="save"><strong>Project JSON</strong><small>Complete editable project and footprint definitions</small></button><button data-action="bom"><strong>Bill of materials · CSV</strong><small>References, values, MPN, side and placement</small></button><button data-action="netlist"><strong>Connection list · CSV</strong><small>Pin-by-pin electrical net assignments</small></button><button data-action="svg"><strong>Drawing · SVG</strong><small>${view==='sch'?'Schematic':'PCB assembly guide'} · scalable and editable</small></button><button data-action="print"><strong>Design report · Print / PDF</strong><small>Metadata, BOM, findings, assumptions and evidence</small></button></div><p class="helptext">No paste, silkscreen, zones or cutouts are exported in this release. On-screen body outlines and labels are assembly guides. Both copper layers share a top-view coordinate system; do not mirror the bottom file.</p>`);}
function standaloneSVG(){let pcb=view!=='sch',vb=pcb?[-3,-3,p.board.width+6,p.board.height+6]:Object.values(viewBox()),content=pcb?boardSVG(true):schematicSVG();return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb.join(' ')}" ${pcb?`width="${p.board.width+6}mm" height="${p.board.height+6}mm"`:''}><title>${esc(p.title)}</title><rect x="${vb[0]}" y="${vb[1]}" width="${vb[2]}" height="${vb[3]}" fill="${pcb?'#fff':prefs.theme==='light'?'#fff':'#173025'}"/>${content.replaceAll('var(--panel)',prefs.theme==='light'?'#fff':'#173025').replaceAll('fill="url(#boardgrid)"','fill="none"')}</svg>`;}
function renderReview(){let fs=CB.checks(p),errors=fs.filter(f=>f.severity==='error').length,warnings=fs.length-errors,visible=fs.filter(f=>checkFilter==='all'||f.severity===checkFilter);$('#review').innerHTML=`<div class="reviewHeading"><div><div class="eyebrow">CHECK THE DESIGN. PREPARE THE BUILD.</div><h2>Ready for the workbench?</h2><p class="helptext">${esc(p.title)} · Revision ${esc(p.revision)}</p></div><button data-action="export" class="primary">Export files ↗</button></div><div class="reviewStats"><div><strong style="color:var(--danger)">${errors}</strong><span>Error findings</span></div><div><strong>${warnings}</strong><span>Warnings</span></div><div><strong>${CB.connections(p).length}</strong><span>Unrouted connections</span></div></div><div class="notice">Checks cover assigned pin types, connectivity, circular copper geometry, annular rings and board-edge clearance. They do not simulate the circuit or check body collisions, creepage, thermal behavior, drill-to-drill clearance or fabrication capability.</div><div class="buttonrow"><select id="checkFilter" aria-label="Filter findings">${options([['all','All findings'],['error','Errors'],['warning','Warnings']],checkFilter)}</select><button data-action="baseline">Capture baseline</button><button data-action="print">Print / PDF report</button></div>${p.baseline?`<p class="helptext" style="margin-top:15px">Baseline ${esc(new Date(p.baseline.at).toLocaleString())}: ${p.components.length-p.baseline.components>=0?'+':''}${p.components.length-p.baseline.components} components, ${p.tracks.length-p.baseline.tracks>=0?'+':''}${p.tracks.length-p.baseline.tracks} tracks, ${errors-p.baseline.errors>=0?'+':''}${errors-p.baseline.errors} errors since capture.</p>`:''}<div class="findings">${visible.map(f=>`<div class="finding"><span class="severity ${f.severity}">${f.severity.toUpperCase()}</span><div><p>${esc(f.message)}</p><small>${f.code} · ${f.confidence} confidence</small></div>${f.target?`<button data-find="${f.target}">Locate</button>`:''}</div>`).join('')||'<p class="helptext">No findings match this filter. Passing these checks does not certify the design.</p>'}</div><details open><summary>Bill of materials · ${p.components.length} parts</summary><div class="buttonrow"><input id="bomSearch" aria-label="Search bill of materials" placeholder="Search BOM…"><button data-action="bomSort">Sort ${bomSort==='ref'?'by value':'by reference'}</button><button data-action="bom">Export CSV</button></div><div id="bomTable"></div></details><details><summary>Assumptions & evidence</summary><label>Assumptions<textarea data-register="assumptions">${esc(p.assumptions)}</textarea></label><label>Evidence / verification notes<textarea data-register="evidence" placeholder="Datasheet dimensions checked, test observations, fabricator review…">${esc(p.evidence)}</textarea></label></details><details><summary>Release scope & next steps</summary><p class="helptext">v0.1.0: shared pin/net model, schematic terminals, two-layer layout, editable footprints, manual routing/vias, basic checks and output files. Planned: v0.2 symbol/footprint library tools and explicit wire paths; v0.3 polygon outlines and copper zones; v0.4 native KiCad board interchange; v0.5 3D assembly and stronger DRC. Native LibrePCB import and SPICE simulation need separate format/engine work.</p></details>`;renderBOM();}
function renderBOM(){let el=$('#bomTable');if(!el)return;let q=$('#bomSearch')?.value.toLowerCase()||'';el.innerHTML=`<div class="tablewrap"><table><thead><tr><th>Reference</th><th>Value</th><th>Footprint</th><th>MPN</th></tr></thead><tbody>${[...p.components].filter(c=>(c.ref+' '+c.value+' '+c.mpn).toLowerCase().includes(q)).sort((a,b)=>a[bomSort].localeCompare(b[bomSort],undefined,{numeric:true})).map(c=>`<tr><td><button class="textbutton" data-find="${c.id}">${esc(c.ref)}</button></td><td>${esc(c.value)}</td><td>${esc(c.footprintName||c.kind)}</td><td>${esc(c.mpn||'—')}</td></tr>`).join('')}</tbody></table></div>`;}
function printReport(){let f=CB.checks(p);$('#printReport').innerHTML=`<h1>CIRCUITBENCH</h1><p>Design review · v${CB.VERSION} · ${esc(new Date().toLocaleString())}</p><h2>${esc(p.title)} / Rev ${esc(p.revision)}</h2><p>${p.board.width} × ${p.board.height} × ${p.board.thickness} mm · two layers · ${p.components.length} components</p><svg xmlns="http://www.w3.org/2000/svg" viewBox="-3 -3 ${p.board.width+6} ${p.board.height+6}">${boardSVG(true).replaceAll('fill="url(#boardgrid)"','fill="none"')}</svg><h2>Findings</h2><p>Geometric, electrical-role and connectivity checks; not a fabrication certification. Includes courtyards and drill spacing. No circuit simulation or physical reference-board validation.</p><table><thead><tr><th>Severity</th><th>Finding</th><th>Confidence</th></tr></thead><tbody>${f.map(x=>`<tr><td>${x.severity}</td><td>${esc(x.message)}</td><td>${x.confidence}</td></tr>`).join('')||'<tr><td colspan="3">No findings in the implemented checks.</td></tr>'}</tbody></table><h2>Bill of materials</h2><table><thead><tr><th>Ref</th><th>Value</th><th>Footprint</th><th>MPN</th></tr></thead><tbody>${p.components.map(c=>`<tr><td>${esc(c.ref)}</td><td>${esc(c.value)}</td><td>${esc(c.footprintName||c.kind)}</td><td>${esc(c.mpn)}</td></tr>`).join('')}</tbody></table><h2>Assumptions</h2><p style="white-space:pre-wrap">${esc(p.assumptions)}</p><h2>Evidence</h2><p style="white-space:pre-wrap">${esc(p.evidence||'No verification evidence recorded.')}</p><h2>Rules & provenance</h2><p>Clearance ${p.rules.clearance} mm; edge ${p.rules.edge} mm; minimum width ${p.rules.minWidth} mm; annular ring ${p.rules.annular} mm. All geometry from this project. Confidence refers to the implemented geometric or pin-type check, not overall circuit safety.</p>${p.baseline?`<p>Baseline: ${esc(p.baseline.title)}, ${esc(p.baseline.at)}; ${p.baseline.errors} errors and ${p.baseline.warnings} warnings.</p>`:''}`;closeDialog();window.print();}
async function importFile(file){if(!file)return;if(file.size>5*1024*1024){say('Project file exceeds the 5 MB import limit.');return;}try{let data=CB.validate(JSON.parse(await file.text()));if(p.components.length&&!confirm('Replace the current project with '+data.title+'? You can undo this import.'))return;checkpoint();p=data;selected=null;route=null;wire=null;activeNet='';changed('Project imported successfully.');fit();closeDialog();}catch(e){say('Import rejected. '+e.message);dialog('Could not open this project',`<p>${esc(e.message)}</p><p class="helptext">Your current project has not changed. Open a CIRCUITBENCH schema 1 or 2 JSON file. Use Project → Import KiCad board for .kicad_pcb files.</p>`);}finally{$('#fileInput').value='';}}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.view){setView(b.dataset.view);return;}if(b.dataset.tool){setTool(b.dataset.tool);return;}if(b.dataset.left){prefs.left=b.dataset.left;libraryQuery='';$('#search').value='';savePrefs();renderLeft();return;}if(b.dataset.add){addPart(b.dataset.add);return;}if(b.dataset.select){pick(b.dataset.select);return;}if(b.dataset.net){activeNet=b.dataset.net;renderCanvas();say('Active net: '+activeNet);return;}if(b.dataset.find){selected=b.dataset.find;setView('pcb');let obj=selectedObject();if(obj){let q=isComponent(obj)?obj.pcb:obj.points?obj.points[0]:obj;zoom.pcb.cx=q.x;zoom.pcb.cy=q.y;zoom.pcb.w=40;renderCanvas();prefs.rightHidden=false;applyTheme();}return;}
 if(b.hasAttribute('data-remove-net')){let n=b.dataset.removeNet;if(!confirm('Remove '+n+', its copper, and its pin assignments?'))return;edit(()=>{p.nets=p.nets.filter(x=>x!==n);p.components.forEach(c=>c.pads.forEach(a=>{if(a.net===n)a.net='';}));p.tracks=p.tracks.filter(t=>t.net!==n);p.vias=p.vias.filter(v=>v.net!==n);if(activeNet===n)activeNet='';},'Net removed.');netsDialog();return;}
 let a=b.dataset.action;if(!a)return;switch(a){case'closeDialog':closeDialog();break;case'help':helpDialog();break;case'project':projectDialog();break;case'projectApply':edit(()=>{p.title=$('#titleEdit').value.trim()||'Untitled circuit';p.revision=$('#revisionEdit').value;},'Project details saved.');closeDialog();break;case'undo':undo();break;case'redo':undo(true);break;case'new':newProject();break;case'sample':newProject(true);break;case'import':$('#fileInput').click();break;case'save':download(slug()+'.circuitbench.json',JSON.stringify(p,null,2),'application/json');break;case'export':exportDialog();break;case'fab':if(CB.checks(p).some(f=>f.severity==='error')&&!confirm('This design has error findings. Export a draft fabrication ZIP with the check report anyway?'))break;download(slug()+'-fabrication.zip',CB.zip(CB.fabrication(p)),'application/zip');break;case'bom':download(slug()+'-bom.csv',CB.bom(p),'text/csv');break;case'netlist':download(slug()+'-netlist.csv',CB.netlist(p),'text/csv');break;case'svg':download(slug()+'-'+(view==='sch'?'schematic':'assembly')+'.svg',standaloneSVG(),'image/svg+xml');break;case'print':printReport();break;case'toggleLeft':prefs.leftHidden=!prefs.leftHidden;if(innerWidth<851&&!prefs.leftHidden)prefs.rightHidden=true;savePrefs();applyTheme();requestAnimationFrame(renderCanvas);break;case'toggleRight':prefs.rightHidden=!prefs.rightHidden;if(innerWidth<851&&!prefs.rightHidden)prefs.leftHidden=true;savePrefs();applyTheme();requestAnimationFrame(renderCanvas);break;case'fit':fit();break;case'zoomIn':zoom[view==='sch'?'sch':'pcb'].w=Math.max(10,zoom[view==='sch'?'sch':'pcb'].w/1.25);renderCanvas();break;case'zoomOut':zoom[view==='sch'?'sch':'pcb'].w=Math.min(1500,zoom[view==='sch'?'sch':'pcb'].w*1.25);renderCanvas();break;case'delete':deleteSelected();break;case'rotate':rotateSelected();break;case'duplicate':duplicateSelected();break;case'crossprobe':setView(view==='sch'?'pcb':'sch');break;case'nets':netsDialog();break;case'addNet':{let n=$('#newNet').value.trim();if(!n||p.nets.includes(n)){say('Enter a unique net name.');return;}edit(()=>p.nets.push(n),'Net added.');netsDialog();break;}case'footprint':footprintDialog();break;case'addPad':{let ns=$$('#padTable [data-pad-field=n]').map(e=>e.value),i=1;while(ns.includes(String(i)))i++;$('#padTable tbody').insertAdjacentHTML('beforeend',padRow(CB.pad(i,0,0)));break;}case'removePadRow':b.closest('tr').remove();break;case'applyFootprint':applyFootprint();break;case'routeDialog':routeDialog();break;case'routeApply':routeApply();break;case'finishRoute':finishRoute();break;case'vertices':verticesDialog();break;case'applyVertices':{let t=selectedObject(),pts=$$('#vertexTable tbody tr').map(r=>({x:Number(r.querySelectorAll('input')[0].value),y:Number(r.querySelectorAll('input')[1].value)}));edit(()=>t.points=pts,'Track geometry updated.');closeDialog();break;}case'baseline':edit(()=>{let f=CB.checks(p);p.baseline={at:new Date().toISOString(),title:p.title,components:p.components.length,tracks:p.tracks.length,vias:p.vias.length,errors:f.filter(x=>x.severity==='error').length,warnings:f.filter(x=>x.severity==='warning').length};},'Baseline captured. Future comparisons show count changes.');break;case'bomSort':bomSort=bomSort==='ref'?'value':'ref';renderReview();break;case'recover':try{let raw=localStorage.getItem(KEY+'.backup');if(!raw){say('No previous autosave is available yet.');return;}let restored=CB.validate(JSON.parse(raw));if(!confirm('Restore the previous autosave? Current work remains available through Undo.'))return;checkpoint();p=restored;selected=null;changed('Previous autosave restored.');closeDialog();fit();}catch(e){say('Recovery failed: '+e.message);}break;case'rawRecovery':try{download('circuitbench-recovery.json',JSON.stringify({current:localStorage.getItem(KEY),previous:localStorage.getItem(KEY+'.backup')},null,2),'application/json');}catch(e){say('Recovery storage is unavailable.');}break;}
});
document.addEventListener('change',e=>{let el=e.target;if(el.id==='theme'||el.id==='mode'){prefs[el.id]=el.value;savePrefs();render();return;}if(el.id==='layer'){let cancelled=!!route;route=null;prefs.layer=el.value;savePrefs();renderCanvas();say((el.value==='F'?'Front':'Back')+' copper active — new parts and routes use this side.'+(cancelled?' Unfinished route cancelled. Use Via transition to change sides during routing.':''));return;}if(el.id==='grid'){renderCanvas();return;}if(['showRats','showOther','showLabels','showWireMap'].includes(el.id)){if(el.id==='showRats')showRats=el.checked;if(el.id==='showOther')showOther=el.checked;if(el.id==='showLabels')showLabels=el.checked;if(el.id==='showWireMap')showWireMap=el.checked;renderCanvas();return;}if(el.id==='checkFilter'){checkFilter=el.value;renderReview();return;}if(el.dataset.register){edit(()=>p[el.dataset.register]=el.value,'Register saved.');return;}
 if(el.hasAttribute('data-rename-net')){let old=el.dataset.renameNet,n=el.value.trim();if(!n||p.nets.includes(n)&&n!==old){say('Net names must be unique and nonempty.');el.value=old;return;}edit(()=>{p.nets=p.nets.map(x=>x===old?n:x);p.components.forEach(c=>c.pads.forEach(a=>{if(a.net===old)a.net=n;}));[...p.tracks,...p.vias].forEach(a=>{if(a.net===old)a.net=n;});if(activeNet===old)activeNet=n;},'Net renamed across the design.');netsDialog();return;}
 if(el.hasAttribute('data-pin-net')){let c=selectedObject(),a=c?.pads.find(a=>a.n===el.dataset.pinNet);if(!a)return;edit(()=>{a.nc=el.value==='__NC__';a.net=a.nc?'':el.value;},'Pin assignment updated. Existing tracks retain their own net until edited.');return;}
 if(el.dataset.field){let k=el.dataset.field,v=el.type==='number'?Number(el.value):el.value,x=selectedObject();edit(()=>{if(k==='boardWidth')CB.resizeBoard(p,v,p.board.height);else if(k==='boardHeight')CB.resizeBoard(p,p.board.width,v);else if(k==='thickness')p.board.thickness=v;else if(k.startsWith('rule:'))p.rules[k.split(':')[1]]=v;else if(x){if(['x','y','rotation'].includes(k)&&isComponent(x))x[view==='sch'?'sch':'pcb'][k]=v;else if(k==='side')x.pcb.side=v;else if(k==='viaX')x.x=v;else if(k==='viaY')x.y=v;else x[k]=v;}},'Properties updated.');}
});
$('#search').addEventListener('input',e=>{libraryQuery=e.target.value;renderLeft();});document.addEventListener('input',e=>{if(e.target.id==='bomSearch')renderBOM();});$('#fileInput').addEventListener('change',e=>importFile(e.target.files[0]));
document.addEventListener('keydown',e=>{if($('#dialog').open)return;let typing=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();download(slug()+'.circuitbench.json',JSON.stringify(p,null,2),'application/json');return;}if(typing)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(e.key==='Escape'){route=null;wire=null;tool='select';render();return;}if(e.key==='Enter'&&route){e.preventDefault();finishRoute();return;}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();return;}if(!e.ctrlKey&&!e.metaKey&&!e.altKey){let k=e.key.toLowerCase();if(k==='s')setTool('select');if(k==='h')setTool('pan');if(k==='w')setTool(view==='sch'?'connect':'route');if(k==='f')fit();if(k==='r')rotateSelected();if(e.key.startsWith('Arrow')){let x=selectedObject();if(!x||x.points)return;e.preventDefault();let step=(view==='sch'?1:Number($('#grid').value))*(e.shiftKey?10:1);edit(()=>{let pos=isComponent(x)?x[view==='sch'?'sch':'pcb']:x;pos.x=CB.round(pos.x+(pcbBackView()?-1:1)*(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0));pos.y=CB.round(pos.y+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0));},'Position nudged.');}}});
document.addEventListener('dragover',e=>{e.preventDefault();});document.addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length)importFile(e.dataTransfer.files[0]);});
window.addEventListener('beforeunload',()=>{if(saveTimer&&typeof flushProject==='function')flushProject();});
new ResizeObserver(()=>requestAnimationFrame(renderCanvas)).observe($('#stage'));
render();requestAnimationFrame(fit);if(loadError){say(loadError);dialog('Local save needs recovery',`<p>${esc(loadError)}</p><button data-action="rawRecovery" class="primary">Download recovery data</button><p class="helptext">Your stored data has not been replaced. Export it before editing the example project.</p>`);}else if(!previous)persist();
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>say('Offline cache unavailable. The downloaded HTML still works offline.'));
window.Circuitbench={version:CB.VERSION,project:()=>CB.clone(p),checks:()=>CB.checks(p)};
